sys_script.script:
(function executeRule(current, previous) {
    var quantity = parseFloat(current.getValue('quantity') || '0');
    var unitCost = parseFloat(current.getValue('unit_cost') || '0');

    if (quantity < 0) {
        gs.addErrorMessage('Quantity cannot be negative.');
        current.setAbortAction(true);
        return;
    }

    if (unitCost < 0) {
        gs.addErrorMessage('Unit cost cannot be negative.');
        current.setAbortAction(true);
        return;
    }

    current.setValue('cost', (quantity * unitCost).toFixed(2));
})(current, previous);
